<template>
  <main class="admin-private-page"><header><div><p>密价运营中心</p><h1>{{ isTerms?'权益周期':'代理协议' }}</h1><p>全局暂停与购买期限独立；恢复只保留原剩余时间，终止不会没收本金。</p></div><el-button :loading="loading" @click="load">刷新列表</el-button></header>
    <el-card><el-form inline @submit.prevent="load"><el-form-item label="代理UUID"><el-input v-model="filters.userUid" aria-label="查询代理UUID" placeholder="公开UUID，不使用内部用户编号" clearable /></el-form-item><el-form-item label="课程商品"><el-input v-model="filters.platformId" aria-label="查询课程商品ID" inputmode="numeric" placeholder="商品编号，可不填" clearable /></el-form-item><el-form-item label="协议状态"><el-select v-model="filters.status" aria-label="查询协议状态" clearable style="width:160px"><el-option v-for="state in states" :key="state" :label="privateState(state)" :value="state" /></el-select></el-form-item><el-button native-type="submit" type="primary">查询</el-button></el-form></el-card>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon />
    <el-card v-loading="loading"><el-empty v-if="!rows.length&&!loading" description="没有匹配的代理协议" /><div class="contract-list"><article v-for="row in rows" :key="isTerms?row.termId:row.contractId"><div class="row-title"><h2>{{ row.platformName }}</h2><el-tag>{{ privateState(row.contractStatus) }}</el-tag></div><p>{{ row.username||'历史账户' }} · {{ row.userUid||'UUID未记录' }}</p><div class="row-metrics"><span>固定价 <strong>¥{{ privateMoney(row.fixedPrice) }}/单</strong></span><span>专户余额 <strong>¥{{ privateMoney(row.walletBalance) }}</strong></span><span>{{ privateMode(row.operationsMode) }} · {{ row.currentTerm?.planName||'原协议' }}</span></div><p>购买期截止：{{ row.validUntil?privateDate(row.validUntil):'未设置结束时间' }}<span v-if="row.currentTerm?.reviewRequired"> · 需要运营复核</span></p><p v-if="isTerms&&row.currentTerm">第 {{ row.currentTerm.termNo }} 期 · {{ privateState(row.currentTerm.status) }} · {{ privateState(row.currentTerm.qualificationStatus) }}</p><div class="row-actions"><el-button type="primary" :disabled="!row.currentTermId" @click="inspect(isTerms?row.termId:row.currentTermId)">查看周期与历史</el-button><template v-if="canAdjust&&!isTerms"><el-button v-if="row.contractStatus!=='SUSPENDED'&&row.contractStatus!=='TERMINATED'" @click="openState(row,'SUSPEND')">暂停协议</el-button><el-button v-if="row.contractStatus==='SUSPENDED'" @click="openState(row,'RESUME')">恢复协议</el-button><el-button v-if="row.contractStatus!=='TERMINATED'" type="danger" plain @click="openState(row,'TERMINATE')">终止关系</el-button><el-button v-if="pendingStates[row.contractId]" @click="openState(row,pendingStates[row.contractId])">核对原状态请求</el-button></template></div></article></div><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load" /></el-card>
    <el-dialog v-model="detailVisible" title="周期详情与审计" width="min(880px,95vw)"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" /><div v-loading="detailLoading"><CoursePrivateTermDetails :is-admin="true" :detail="detail" @inspect="inspect" /><el-button v-if="canResolve&&(reviewPending||detail?.term?.reviewRequired&&detail?.latestSettlement?.id)" type="warning" @click="openReview">{{ reviewPending?'核对原复核处理':'确认当前净事实并解除复核' }}</el-button></div></el-dialog>
    <el-dialog v-model="reviewVisible" title="处理原周期事实复核" width="min(560px,95vw)" :close-on-click-modal="!busy" :show-close="!busy"><el-alert title="只确认原订单当前净事实；已执行下一期和原终局时间保留，不补扣差价或回填达标。仍有证据矛盾时后端会拒绝解除。" type="warning" :closable="false" /><el-form label-position="top"><el-form-item label="复核原因"><el-input v-model="review.reason" aria-label="周期复核原因" type="textarea" maxlength="255" :disabled="busy||reviewRecovering" /></el-form-item><el-form-item label="核验依据"><el-input v-model="review.evidence" aria-label="周期复核核验依据" type="textarea" maxlength="2000" :disabled="busy||reviewRecovering" /></el-form-item></el-form><el-alert v-if="reviewError" :title="reviewError" type="error" :closable="false" /><template #footer><el-button :disabled="busy" @click="reviewVisible=false">取消</el-button><el-button v-if="reviewRejected" :disabled="busy" @click="refreshRejectedReview">重新核对当前结算</el-button><el-button type="primary" :loading="busy" @click="submitReview">{{ reviewRecovering?'核对原复核结果':'确认当前净事实' }}</el-button></template></el-dialog>
    <el-dialog v-model="stateVisible" :title="actionLabel(state.action)" width="min(540px,95vw)" :close-on-click-modal="!busy" :show-close="!busy"><p>{{ selected?.username }} · {{ selected?.platformName }}</p><el-alert :title="state.action==='TERMINATE'?'终止会取消未生效下一期并停止购买。预存余额、历史订单和退款身份保留，重新签约须另行申请。':state.action==='RESUME'?'恢复不重新起算期限；已到期的原权益仍不可购买。':'暂停期间不能购课或新增权益，原到期时间继续计算。'" type="warning" :closable="false" show-icon /><el-form label-position="top"><el-form-item label="操作原因"><el-input v-model="state.reason" aria-label="协议状态操作原因" type="textarea" maxlength="255" :disabled="busy||recovering" /></el-form-item></el-form><el-alert v-if="stateError" :title="stateError" type="error" :closable="false" /><el-alert v-if="recovering" title="按已保存的原状态请求核对；原操作完成后不会再次改变当前状态。" type="info" :closable="false" /><template #footer><el-button :disabled="busy" @click="stateVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitState">{{ recovering?'核对原状态请求':'确认状态调整' }}</el-button></template></el-dialog>
  </main>
</template>
<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {ElMessage} from 'element-plus';
import {getPrivateContracts,getAdminPrivateTerms,getPrivateTerm,changePrivateContract,resolvePrivateReview} from '@/api/coursePrivateOperations';import {sessionUserInfo} from '@/utils/authSession';import {hasPermission} from '@/utils/permissions';import {privateDate,privateMoney,privateState,privateMode,createPrivateRequests} from '@/utils/coursePrivateOperations';import CoursePrivateTermDetails from '@/components/CoursePrivateTermDetails.vue';
const route=useRoute(),isTerms=computed(()=>route.path.endsWith('/terms')),canAdjust=computed(()=>hasPermission(sessionUserInfo.value,'course-private-term:adjust'));
const canResolve=computed(()=>hasPermission(sessionUserInfo.value,'course-private-term:adjust')&&hasPermission(sessionUserInfo.value,'course-private-settlement:execute'));
const reviewVisible=ref(false),reviewError=ref(''),reviewPending=ref(false),reviewRecovering=ref(false),reviewRejected=ref(false),review=reactive({expectedVersion:0,expectedSettlementId:null,reason:'',evidence:''});
const states=computed(()=>isTerms.value?['PENDING_ACTIVATION','SCHEDULED','ACTIVE','PENDING_SETTLEMENT','QUALIFIED','RENEWED','EXPIRED','CANCELLED','SUPERSEDED','SUSPENDED','TERMINATED']:['PENDING_ACTIVATION','ACTIVE','SUSPENDED','EXPIRED','TERMINATED']),filters=reactive({userUid:'',platformId:'',status:''}),rows=ref([]),page=ref(1),total=ref(0),loading=ref(false),error=ref('');
const detailVisible=ref(false),detailLoading=ref(false),detailError=ref(''),detail=ref(null),selected=ref(null),stateVisible=ref(false),stateError=ref(''),busy=ref(false),recovering=ref(false),state=reactive({expectedVersion:0,action:'',reason:''}),pendingStates=reactive({});
const keys=createPrivateRequests({userUid:()=>sessionUserInfo.value?.uid}),scope=(row,action)=>`state:${row.contractId}:${action}`;
const actionLabel=action=>({SUSPEND:'暂停协议',RESUME:'恢复协议',TERMINATE:'终止关系'}[action]||'调整协议');
async function load(){loading.value=true;error.value='';try{const params={page:page.value,pageSize:20};if(filters.userUid.trim())params.userUid=filters.userUid.trim();if(filters.platformId.trim())params.platformId=filters.platformId.trim();if(filters.status)params.status=filters.status;const response=await (isTerms.value?getAdminPrivateTerms(params):getPrivateContracts(params));rows.value=response.data.records||[];total.value=response.data.total||0;for(const key of Object.keys(pendingStates))delete pendingStates[key];if(canAdjust.value)for(const row of rows.value)for(const action of ['SUSPEND','RESUME','TERMINATE'])if(keys.peek(scope(row,action)))pendingStates[row.contractId]=action;}catch(e){error.value=e.message||'协议列表读取失败，请重试';}finally{loading.value=false;}}
async function inspect(id){detailVisible.value=true;detailLoading.value=true;detailError.value='';detail.value=null;try{detail.value=(await getPrivateTerm(id,true)).data;reviewPending.value=canResolve.value&&!!keys.peek(`review:${id}`);}catch(e){detailError.value=e.message||'周期详情读取失败';}finally{detailLoading.value=false;}}
function openState(row,action){if(busy.value)return;selected.value=row;stateError.value='';try{const prior=keys.peek(scope(row,action));recovering.value=!!prior;Object.assign(state,prior?.body||{expectedVersion:row.contractVersion,action,reason:''});stateVisible.value=true;}catch(e){ElMessage.error(e.message);}}
async function submitState(){if(busy.value)return;stateError.value='';try{if(!state.reason.trim())throw new Error('请填写明确的操作原因');const name=scope(selected.value,state.action);const saved=keys.begin(name,{expectedVersion:state.expectedVersion,action:state.action,reason:state.reason.trim()});busy.value=true;await changePrivateContract(selected.value.contractId,{...saved.body,requestKey:saved.requestKey});keys.confirmed(name,saved.requestKey);stateVisible.value=false;await load();ElMessage.success('状态调整已核对，原本金与期限保留');}catch(e){stateError.value=e.message||'结果未知，请核对原请求后重试';try{recovering.value=!!keys.peek(scope(selected.value,state.action));}catch{} }finally{busy.value=false;}}
// 未知响应保留原版本和结算记录，处理完成后仍能核对原请求。
function openReview(){if(busy.value||!detail.value?.term)return;reviewError.value='';reviewRejected.value=false;try{const prior=keys.peek(`review:${detail.value.term.id}`);reviewRecovering.value=!!prior;Object.assign(review,prior?.body||{expectedVersion:detail.value.term.version,expectedSettlementId:detail.value.latestSettlement.id,reason:'',evidence:''});reviewVisible.value=true;}catch(e){ElMessage.error(e.message);}}
async function refreshRejectedReview(){if(busy.value||!reviewRejected.value)return;try{const id=detail.value.term.id,name=`review:${id}`;const prior=keys.peek(name);if(prior)keys.confirmed(name,prior.requestKey);reviewVisible.value=false;await inspect(id);reviewRejected.value=false;if(detail.value?.term?.reviewRequired)openReview();else ElMessage.info('当前复核已处理，请查看最新结算与审计');}catch(e){reviewError.value=e.message||'原结算重新核对失败';}}
async function submitReview(){if(busy.value)return;reviewError.value='';try{if(!review.reason.trim()||!review.evidence.trim())throw new Error('请填写复核原因与明确核验依据');const id=detail.value.term.id,name=`review:${id}`;const saved=keys.begin(name,{expectedVersion:review.expectedVersion,expectedSettlementId:review.expectedSettlementId,reason:review.reason.trim(),evidence:review.evidence.trim()});busy.value=true;await resolvePrivateReview(id,{...saved.body,requestKey:saved.requestKey});keys.confirmed(name,saved.requestKey);reviewVisible.value=false;await inspect(id);await load();ElMessage.success('原净事实复核已核对，既有权益与本金保留');}catch(e){reviewError.value=e.message||'复核结果未知，请核对原请求';reviewRejected.value=[-2,-110].includes(e.businessCode??e.response?.data?.code);try{reviewRecovering.value=!!keys.peek(`review:${detail.value.term.id}`);}catch{reviewRecovering.value=false;}}finally{busy.value=false;}}
watch(isTerms,()=>{page.value=1;filters.status='';load();});onMounted(load);
</script>
<style scoped>
.admin-private-page{width:100%;box-sizing:border-box;grid-template-columns:minmax(0,1fr);padding:22px;display:grid;gap:18px;max-width:1400px;margin:auto}.admin-private-page>header{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}h1{font-size:26px;margin:5px 0 9px}header p{margin:0;color:var(--el-text-color-secondary)}.contract-list article{border-bottom:1px solid var(--el-border-color-light);padding:20px 0}.contract-list article:first-child{padding-top:0}.row-title{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.row-title h2{font-size:18px;margin:0}.contract-list p{font-size:13px;color:var(--el-text-color-secondary);overflow-wrap:anywhere}.row-metrics{display:flex;gap:22px;flex-wrap:wrap}.row-metrics strong{color:var(--el-text-color-primary)}.row-actions{display:flex;gap:8px;flex-wrap:wrap}.row-actions .el-button{margin:0}.el-pagination{margin-top:20px;overflow:auto}.el-form .el-input{width:260px}.admin-private-page>*{min-width:0}header>div{min-width:0;max-width:100%}@media(max-width:600px){.admin-private-page{padding:12px}.el-form--inline .el-form-item{display:block;margin-right:0}.el-form .el-input{width:100%}.row-metrics{display:grid;gap:8px}h1{font-size:23px}}
</style>
